import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Diagnosticar una operación fallida","description":"","frontmatter":{"title":"Diagnosticar una operación fallida","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2182472a23e41229c1665cfa2b621c39b05cd0c899ae8e81889ba59fda126525","translationRevision":"8c1757aa2512bd54435e67f0b327f05240c4ec6e0620262ec6a34009c83aa86b","order":30},"headers":[],"relativePath":"es/user/preferences/troubleshooting.md","filePath":"es/user/preferences/troubleshooting.md","lastUpdated":1795727787000}`),s={name:`es/user/preferences/troubleshooting.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="diagnose-a-failed-operation" tabindex="-1">Diagnosticar una operación fallida <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to “Diagnosticar una operación fallida”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Identifica el componente que falla y reúne un informe útil sin repetir efectos continuamente. Necesitas la versión, la hora aproximada y la operación intentada. Conserva una <a href="./backups.html">copia</a> antes de reiniciar o sustituir datos.</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">Inspeccionar la evidencia cercana <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to “Inspeccionar la evidencia cercana”">​</a></h2><ol><li>Lee el error mostrado donde ocurrió el fallo. Usa su acción de diagnóstico o abre <strong>Diagnostics</strong> para inspeccionar las entradas relacionadas.</li><li>Filtra por origen, nivel o texto. Entre los orígenes útiles están LIVE, supervisión, plugins, cuenta, sincronización, actualizaciones, transporte, catálogo, instalación y colaboración.</li><li>Selecciona la entrada pertinente y conserva hora, código, identificadores de solicitud/entidad y descripción breve. Despliega los detalles disponibles.</li><li>Copia los diagnósticos filtrados o exporta el informe de texto. Si falla el portapapeles o la exportación, utiliza el texto alternativo mostrado. Revísalo antes de compartir y elimina tokens, cookies, enlaces de invitación y contenido privado.</li><li>Incluye una reproducción breve: página, creador/perfil/plugin seleccionado, acción, resultado esperado y resultado real. Indica si ocurrió antes o después de actualizar.</li></ol><h2 id="isolate-common-failures" tabindex="-1">Aislar fallos comunes <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to “Aislar fallos comunes”">​</a></h2><p>Si el feed está vacío, borra búsqueda y filtros, reanuda el desplazamiento y confirma la <a href="./../live/connections.html">conexión</a>. Pausar la vista no desconecta. Un aviso de pérdida visual no demuestra que puntos o estadísticas perdieran el mismo evento.</p><p>Si no se ejecuta una automatización, comprueba perfil activo, interruptores de evento/acción, disparador, rutas de campos y espera. Inspecciona el historial antes de modificar efectos. <strong>Test</strong> puede ejecutar audio, HTTP, puntos y acciones de plugins.</p><p>Para plugins, lee el error del trabajo de instalación o de conexión. Para Cloud, revisa la sesión y el área afectada en lugar de cambiar una cookie de TikTok. Para superposiciones, inspecciona pasarela y fuente. Para actualizaciones, consulta la <a href="./../updates.html">vía manual</a> cuando no se pueda instalar.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Están disponibles filtros, copia y exportación de diagnósticos. Un paquete también requiere sus recursos web y el entorno de plataforma. En Linux, verifica GTK/WebKitGTK y una sesión X11/XWayland compatible; en Windows, WebView2. Consulta el alcance de <a href="./../requirements.html">requisitos</a>.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperación”">​</a></h2><p>Repite después de corregir la causa concreta. Ante conflictos de revisión, carga y revisa el estado guardado actual. Si una orden remota queda sin confirmar, inspecciona su historial/estado antes de enviarla otra vez: el efecto puede haberse producido pese al tiempo de espera. Si falla el inicio, informa de paquete, versión y registro; evita borrar el directorio de datos.</p>`,13),t(d,{id:`diagnostics`,locale:`es`,title:`Demo de diagnostics`}),o[1]||=r('<h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>Diagnostics es un registro UI en memoria, limitado a 2.000 entradas o 2 MiB. Agrupa repeticiones dentro de cinco segundos. Muestra inicialmente 100; exportar incluye todas las entradas filtradas, mientras <strong>Limpiar</strong> borra el registro entero. Copia/exporta antes de cerrar, reiniciar, limpiar o cambiar/cerrar una cuenta Cloud conocida: esos cambios vacían este historial.</p><p>Si no aparece ventana, revisa <code>tiktools.log</code> nativo (<code>controller.log</code> en modo controlador) en <code>%LOCALAPPDATA%/TikTools/logs</code> en Windows o <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> en Linux. <code>TIKTOOLS_HOME</code> cambia la raíz y <code>TIKTOOLS_LOG_DIR</code> sustituye el directorio de logs. Si falla el propio registro, puede no existir archivo; conserva el error de terminal/inicio disponible. Los logs nativos no garantizan la redacción de la UI: revisa todo antes de compartir.</p><h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>versión del host e información del runtime</td></tr><tr><td><code>tiktools system health</code></td><td>informe de salud de los componentes</td></tr><tr><td><code>tiktools system snapshot</code></td><td>instantánea completa del estado para depuración</td></tr><tr><td><code>tiktools system doctor</code></td><td>diagnosticar problemas comunes de configuración</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>pedir acceso de entrada al usuario del escritorio</td></tr><tr><td><code>tiktools system shutdown</code></td><td>apagar el host en ejecución <strong>destructivo</strong></td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>',7)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};